: sum-loop
  (forall ρ; ρ xs:Seq Int^many sum:Int^many i:Int^many -- ρ result:Int^many)
  locals { xs sum i } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at sum prim + locals { new-sum } { xs new-sum i 1 prim + sum-loop }
    ]
    [
      sum
    ]
    if
  };

