  (forall ρ; ρ xs:Seq Int^many sorted:Bool^many i:Int^many -- ρ result:Bool^many)
  locals { xs sorted i } {
    sorted
    [
      i xs prim seq-int.len 1 prim - prim <
      [
        xs i prim seq-int.at xs i 1 prim + prim seq-int.at prim < prim not
        [
          false
        ]
        [
          xs sorted i 1 prim + check-sorted
        ]
        if
      ]
      [
        true
      ]
      if
