      [
        xs i prim seq-int.at xs i 1 prim - prim seq-int.at prim =
        [
          runlen 1 prim +
        ]
        [
          1
        ]
        if
      ]
      if locals { cur-len } { cur-len maxlen prim < [ cur-len ] [ maxlen ] if locals { new-max } { xs new-max i 1 prim + run-loop } }
