: pair-search
  (forall ρ; ρ xs:Seq Int^many target:Int^many found:Bool^many i:Int^many -- ρ result:Bool^many)
  locals { xs target found i } {
    found
    [
      true
    ]
    [
      i xs prim seq-int.len prim <
      [
        xs target i i 1 prim + pair-inner
      ]
      [
